          "steelblue",
          "salmon"
        ]
      },
      "title": "Sex",
      "type": "nominal"
    },
    "x": {
      "axis": {
        "format": "s",
        "labelExpr": "abs(datum.value)"
      },
      "field": "signed",
      "title": "Population",
